(()=>{function e(){var e=Array.from(document.querySelectorAll(".is-style-fit-to-screen"));if(0<e.length){let n=document.body.clientWidth;e.map(e=>{var t=e.parentElement.getBoundingClientRect().x;e.style.width=n+"px",e.style.left=`-${t}px`,console.log(t)})}}window.addEventListener("resize",e()),e()})();